package io.baozhu.copilot.ai; import io.baozhu.copilot.api.*; import org.springframework.stereotype.Component; import java.util.*; @Component public class HeuristicAiProvider implements AiProvider { public String name(){return "heuristic";} public List<RuleSuggestion> suggestRules(String table,List<ColumnSpec> columns,List<Map<String,Object>> samples,String d){List<RuleSuggestion> r=new ArrayList<>(); for(ColumnSpec c:columns){String n=c.name().toLowerCase(); if(!c.nullable()||n.equals("id")||n.endsWith("_id"))r.add(new RuleSuggestion("NOT_NULL",c.name(),"Required or identifier-like column","ERROR",.96)); if(c.unique()||n.equals("id"))r.add(new RuleSuggestion("UNIQUE",c.name(),"Uniqueness is expected from metadata","ERROR",.94)); if(c.type().toLowerCase().contains("amount")||n.contains("amount")||n.contains("price"))r.add(new RuleSuggestion("NON_NEGATIVE",c.name(),"Amount-like fields should not be negative","WARN",.82)); if(c.type().toLowerCase().contains("timestamp")||n.endsWith("_at"))r.add(new RuleSuggestion("FRESHNESS",c.name(),"Timestamp fields should be checked for stale/future rows","WARN",.79));} if(samples!=null&&samples.isEmpty())r.add(new RuleSuggestion("ROW_COUNT_MIN","1","Reject empty partitions","WARN",.68)); return r;} }